# Analyze spatial patterns for each non-background number
# 6 seems to be the background

import numpy as np
grid = np.array(grid)

# For each non-background number, let's see if they appear in patterns
# Let's look at contiguous regions or specific structures

def find_contiguous_regions(arr, value):
    """Find contiguous (8-connected or 4-connected) regions of a value"""
    mask = arr == value
    regions = []

    visited = set()
    regions = []
    for r in range(len(arr)):
        for c in range(len(arr[0])):
            if mask[r, c] and (r, c) not in visited:
                region = []
                stack = [(r, c)]
                connected = {(r, c)}
                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    region.append((cr, cc))
                    # 8-connectivity
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < len(arr) and 0 <= nc < len(arr[0]):
                                if mask[nr, nc] and (nr, nc) not in connected:
                                    connected.add((nr, nc))
                                    stack.append((nr, nc))
                regions.append(len(region))
    return regions

# Let's look at regions for each number
for num in [0, 3, 4, 5, 8]:
    regions = find_contiguous_regions(grid, num)
    print(f"Number {num}: {len(regions)} regions of sizes: {sorted(regions, reverse=True)[:10]}")

